"use client";

import {
	closestCenter,
	DndContext,
	type DragEndEvent,
	DragOverlay,
	type DragStartEvent,
	KeyboardSensor,
	PointerSensor,
	useSensor,
	useSensors,
} from "@dnd-kit/core";
import {
	SortableContext,
	sortableKeyboardCoordinates,
	verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import type { Question } from "@orksys-survey/db";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { ClipboardList, GripVertical, Plus } from "lucide-react";
import { useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { orpc } from "@/utils/orpc";
import { useSurveyBuilder } from "./index";
import { QuestionCard } from "./question-card";

interface BuilderCanvasProps {
	questions: Question[];
	onQuestionsChange: (questions: Question[]) => void;
}

export function BuilderCanvas({
	questions,
	onQuestionsChange,
}: BuilderCanvasProps) {
	const { survey, selectedQuestionId, setSelectedQuestionId, activeTab } =
		useSurveyBuilder();
	const [activeId, setActiveId] = useState<string | null>(null);

	const queryClient = useQueryClient();

	const reorderMutation = useMutation(
		orpc.question.reorder.mutationOptions({
			onSuccess: () => {
				queryClient.invalidateQueries({ queryKey: ["question"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to reorder questions");
			},
		}),
	);

	const createMutation = useMutation(
		orpc.question.create.mutationOptions({
			onSuccess: (newQuestion) => {
				onQuestionsChange([...questions, newQuestion]);
				setSelectedQuestionId(newQuestion.id);
				queryClient.invalidateQueries({ queryKey: ["question"] });
				toast.success("Question added");
			},
			onError: (error) => {
				toast.error(error.message || "Failed to create question");
			},
		}),
	);

	const sensors = useSensors(
		useSensor(PointerSensor, {
			activationConstraint: {
				distance: 5,
			},
		}),
		useSensor(KeyboardSensor, {
			coordinateGetter: sortableKeyboardCoordinates,
		}),
	);

	const handleDragStart = (event: DragStartEvent) => {
		setActiveId(event.active.id as string);
	};

	const handleDragEnd = (event: DragEndEvent) => {
		const { active, over } = event;
		setActiveId(null);

		if (over && active.id !== over.id) {
			const oldIndex = (questions || []).findIndex((q) => q.id === active.id);
			const newIndex = (questions || []).findIndex((q) => q.id === over.id);

			const newQuestions = [...(questions || [])];
			const [removed] = newQuestions.splice(oldIndex, 1);
			newQuestions.splice(newIndex, 0, removed);

			// Update order values
			const reorderedQuestions = newQuestions.map((q, index) => ({
				...q,
				order: index,
			}));

			onQuestionsChange(reorderedQuestions);

			// Persist to server
			reorderMutation.mutate({
				questions: reorderedQuestions.map((q) => ({
					id: q.id,
					order: q.order,
				})),
			});
		}
	};

	const handleAddQuestion = () => {
		createMutation.mutate({
			surveyId: survey.id,
			type: "text",
			title: "New Question",
			order: (questions || []).length,
		});
	};

	const activeQuestion = activeId
		? (questions || []).find((q) => q.id === activeId)
		: null;

	const safeQuestions = questions || [];

	if (activeTab === "preview") {
		return (
			<div className="flex flex-1 items-center justify-center overflow-y-auto bg-neutral-50 p-8">
				<div className="w-full max-w-2xl">
					{safeQuestions.length === 0 ? (
						<Card className="border-dashed">
							<CardContent className="flex flex-col items-center justify-center py-16">
								<ClipboardList className="mb-4 h-12 w-12 text-neutral-300" />
								<p className="text-neutral-500">
									Add questions to preview your survey
								</p>
							</CardContent>
						</Card>
					) : (
						<div className="space-y-6">
							{safeQuestions.map((question, index) => (
								<Card key={question.id}>
									<CardContent className="p-6">
										<div className="mb-4">
											<span className="mb-2 block font-bold text-[10px] text-violet-500 uppercase tracking-widest">
												Question {index + 1} of {safeQuestions.length}
											</span>
											<h2 className="font-semibold text-lg">
												{question.title}
											</h2>
											{question.description && (
												<p className="mt-1 text-neutral-500 text-sm">
													{question.description}
												</p>
											)}
										</div>
										<div className="rounded-lg border border-neutral-200 border-dashed bg-neutral-50 p-4 text-center text-neutral-400 text-sm">
											{question.type.replace("_", " ")} question preview
										</div>
									</CardContent>
								</Card>
							))}
						</div>
					)}
				</div>
			</div>
		);
	}

	return (
		<div className="flex flex-1 flex-col overflow-y-auto bg-neutral-50/50 p-6">
			<DndContext
				sensors={sensors}
				collisionDetection={closestCenter}
				onDragStart={handleDragStart}
				onDragEnd={handleDragEnd}
			>
				<div className="mx-auto w-full max-w-2xl space-y-4">
					{safeQuestions.length === 0 ? (
						<Card
							className="cursor-pointer border-dashed transition-colors hover:border-violet-300 hover:bg-violet-50/50"
							onClick={handleAddQuestion}
						>
							<CardContent className="flex flex-col items-center justify-center py-16">
								<div className="mb-4 rounded-full bg-violet-100 p-4">
									<Plus className="h-8 w-8 text-violet-500" />
								</div>
								<p className="font-semibold text-neutral-900">
									Add your first question
								</p>
								<p className="mt-1 text-neutral-500 text-sm">
									Click here or drag a question type from the left panel
								</p>
							</CardContent>
						</Card>
					) : (
						<>
							<SortableContext
								items={safeQuestions.map((q) => q.id)}
								strategy={verticalListSortingStrategy}
							>
								{safeQuestions.map((question) => (
									<QuestionCard
										key={question.id}
										question={question}
										isSelected={selectedQuestionId === question.id}
										onSelect={() => setSelectedQuestionId(question.id)}
										questions={safeQuestions}
										onQuestionsChange={onQuestionsChange}
									/>
								))}
							</SortableContext>

							<Button
								variant="outline"
								className="w-full border-dashed"
								onClick={handleAddQuestion}
								disabled={createMutation.isPending}
							>
								<Plus className="mr-2 h-4 w-4" />
								Add Question
							</Button>
						</>
					)}
				</div>

				<DragOverlay>
					{activeQuestion && (
						<Card className="shadow-lg">
							<CardContent className="flex items-center gap-3 p-4">
								<GripVertical className="h-4 w-4 text-neutral-400" />
								<span className="font-medium">{activeQuestion.title}</span>
							</CardContent>
						</Card>
					)}
				</DragOverlay>
			</DndContext>
		</div>
	);
}

