"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { Question } from "@orksys-survey/db";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import {
	Bolt,
	Calendar,
	CheckSquare,
	ChevronsUpDown,
	ClipboardList,
	FileText,
	GripVertical,
	Hash,
	ListChecks,
	Mail,
	MoreHorizontal,
	Phone,
	Star,
	Text,
	Trash2,
	TrendingUp,
} from "lucide-react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import { orpc } from "@/utils/orpc";

interface QuestionCardProps {
	question: Question;
	isSelected: boolean;
	onSelect: () => void;
	questions: Question[];
	onQuestionsChange: (questions: Question[]) => void;
}

const questionTypeIcons: Record<string, React.ElementType> = {
	text: Text,
	textarea: FileText,
	multiple_choice: CheckSquare,
	checkbox: ListChecks,
	dropdown: ChevronsUpDown,
	rating: Star,
	nps: TrendingUp,
	linear_scale: Hash,
	date: Calendar,
	email: Mail,
	phone: Phone,
	file_upload: ClipboardList,
};

const questionTypeLabels: Record<string, string> = {
	text: "Short Text",
	textarea: "Long Text",
	multiple_choice: "Multiple Choice",
	checkbox: "Checkboxes",
	dropdown: "Dropdown",
	rating: "Rating",
	nps: "NPS",
	linear_scale: "Linear Scale",
	date: "Date",
	email: "Email",
	phone: "Phone",
	file_upload: "File Upload",
};

export function QuestionCard({
	question,
	isSelected,
	onSelect,
	questions,
	onQuestionsChange,
}: QuestionCardProps) {
	const queryClient = useQueryClient();

	const {
		attributes,
		listeners,
		setNodeRef,
		transform,
		transition,
		isDragging,
	} = useSortable({ id: question.id });

	const deleteMutation = useMutation(
		orpc.question.delete.mutationOptions({
			onSuccess: () => {
				onQuestionsChange(questions.filter((q) => q.id !== question.id));
				queryClient.invalidateQueries({ queryKey: ["question"] });
				toast.success("Question deleted");
			},
			onError: (error) => {
				toast.error(error.message || "Failed to delete question");
			},
		}),
	);

	// Query logic rules to check if this question has any
	const logicRules = useQuery(
		orpc.logicRule.list.queryOptions({
			input: { surveyId: question.surveyId },
		}),
	);

	const hasLogic = logicRules.data?.some(
		(rule) => rule.sourceQuestionId === question.id,
	);

	const style = {
		transform: CSS.Transform.toString(transform),
		transition,
	};

	const Icon = questionTypeIcons[question.type] || Text;

	return (
		<Card
			ref={setNodeRef}
			style={style}
			className={cn(
				"cursor-pointer transition-all",
				isSelected && "border-violet-500 ring-1 ring-violet-500",
				isDragging && "opacity-50 shadow-lg",
			)}
			onClick={onSelect}
		>
			<CardContent className="flex items-start gap-3 p-4">
				<button
					type="button"
					className="mt-1 cursor-grab touch-none"
					{...attributes}
					{...listeners}
				>
					<GripVertical className="h-4 w-4 text-neutral-400" />
				</button>

				<div className="flex h-8 w-8 shrink-0 items-center justify-center rounded bg-violet-100">
					<Icon className="h-4 w-4 text-violet-600" />
				</div>

				<div className="min-w-0 flex-1">
					<div className="flex items-center gap-2">
						<h3 className="truncate font-medium text-sm">{question.title}</h3>
						{question.required && <span className="text-red-500">*</span>}
						{hasLogic && (
							<span className="flex items-center gap-1 rounded bg-violet-100 px-1.5 py-0.5 font-medium text-[10px] text-violet-600">
								<Bolt className="h-3 w-3" />
								Logic
							</span>
						)}
					</div>
					<p className="mt-0.5 text-neutral-500 text-xs">
						{questionTypeLabels[question.type]}
						{question.description &&
							` • ${question.description.slice(0, 50)}${question.description.length > 50 ? "..." : ""}`}
					</p>
				</div>

				<DropdownMenu>
					<DropdownMenuTrigger
						render={
							<Button
								variant="ghost"
								size="icon"
								className="shrink-0"
								onClick={(e) => e.stopPropagation()}
							/>
						}
					>
						<MoreHorizontal className="h-4 w-4" />
					</DropdownMenuTrigger>
					<DropdownMenuContent align="end">
						<DropdownMenuItem
							className="text-red-600"
							onClick={(e) => {
								e.stopPropagation();
								deleteMutation.mutate({ id: question.id });
							}}
						>
							<Trash2 className="mr-2 h-4 w-4" />
							Delete
						</DropdownMenuItem>
					</DropdownMenuContent>
				</DropdownMenu>
			</CardContent>
		</Card>
	);
}

"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import {
	ArrowLeft,
	Eye,
	Hammer,
	Loader2,
	MoreHorizontal,
	Send,
	Settings,
} from "lucide-react";
import Link from "next/link";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuSeparator,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { orpc } from "@/utils/orpc";

import { useSurveyBuilder } from "./index";

const statusColors: Record<string, string> = {
	draft: "bg-neutral-100 text-neutral-600",
	published: "bg-green-100 text-green-700",
	closed: "bg-orange-100 text-orange-700",
	archived: "bg-neutral-100 text-neutral-500",
};

export function BuilderHeader() {
	const { survey, activeTab, setActiveTab } = useSurveyBuilder();
	const queryClient = useQueryClient();

	const publishMutation = useMutation(
		orpc.survey.changeStatus.mutationOptions({
			onSuccess: () => {
				toast.success("Survey published!");
				queryClient.invalidateQueries({ queryKey: ["survey"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to publish survey");
			},
		}),
	);

	const handlePublish = () => {
		if (survey.status === "draft") {
			publishMutation.mutate({ id: survey.id, status: "published" });
		}
	};

	return (
		<header className="z-20 flex shrink-0 items-center justify-between border-neutral-100 border-b bg-white px-6 py-3">
			<div className="flex items-center gap-4">
				<Button variant="ghost" size="sm" asChild>
					<Link href="/surveys">
						<ArrowLeft className="mr-2 h-4 w-4" />
						Back
					</Link>
				</Button>
				<div className="flex items-center gap-2 font-sans font-semibold text-neutral-900 text-sm">
					<span className="text-neutral-400">Surveys /</span>
					<span>{survey.title}</span>
					<Badge variant="secondary" className={statusColors[survey.status]}>
						{survey.status}
					</Badge>
				</div>
			</div>

			{/* Tab Navigation */}
			<div className="flex gap-1 rounded-lg bg-neutral-100 p-1">
				<button
					type="button"
					onClick={() => setActiveTab("build")}
					className={`flex items-center gap-2 rounded-md px-4 py-1.5 font-sans font-semibold text-xs transition-colors ${
						activeTab === "build"
							? "bg-white text-neutral-900 shadow-sm"
							: "text-neutral-500 hover:text-neutral-900"
					}`}
				>
					<Hammer className="h-3.5 w-3.5" />
					Build
				</button>
				<button
					type="button"
					onClick={() => setActiveTab("preview")}
					className={`flex items-center gap-2 rounded-md px-4 py-1.5 font-sans font-semibold text-xs transition-colors ${
						activeTab === "preview"
							? "bg-white text-neutral-900 shadow-sm"
							: "text-neutral-500 hover:text-neutral-900"
					}`}
				>
					<Eye className="h-3.5 w-3.5" />
					Preview
				</button>
			</div>

			<div className="flex items-center gap-3">
				<DropdownMenu>
					<DropdownMenuTrigger render={<Button variant="ghost" size="icon" />}>
						<MoreHorizontal className="h-4 w-4" />
					</DropdownMenuTrigger>
					<DropdownMenuContent align="end">
						<DropdownMenuItem>
							<Settings className="mr-2 h-4 w-4" />
							Survey Settings
						</DropdownMenuItem>
						<DropdownMenuSeparator />
						<DropdownMenuItem className="text-red-600">
							Delete Survey
						</DropdownMenuItem>
					</DropdownMenuContent>
				</DropdownMenu>

				{survey.status === "draft" ? (
					<Button onClick={handlePublish} disabled={publishMutation.isPending}>
						{publishMutation.isPending ? (
							<Loader2 className="mr-2 h-4 w-4 animate-spin" />
						) : (
							<Send className="mr-2 h-4 w-4" />
						)}
						Publish
					</Button>
				) : (
					<Button variant="outline" asChild>
						<a
							href={`/s/${survey.slug}`}
							target="_blank"
							rel="noopener noreferrer"
						>
							<Eye className="mr-2 h-4 w-4" />
							View Survey
						</a>
					</Button>
				)}
			</div>
		</header>
	);
}

