     1→"use client";
     2→
     3→import {
     4→	closestCenter,
     5→	DndContext,
     6→	type DragEndEvent,
     7→	type DragOverEvent,
     8→	DragOverlay,
     9→	type DragStartEvent,
    10→	KeyboardSensor,
    11→	PointerSensor,
    12→	useSensor,
    13→	useSensors,
    14→} from "@dnd-kit/core";
    15→import {
    16→	arrayMove,
    17→	SortableContext,
    18→	sortableKeyboardCoordinates,
    19→	verticalListSortingStrategy,
    20→} from "@dnd-kit/sortable";
    21→import type { Question, Survey } from "@orksys-survey/db";
    22→import { useMutation, useQueryClient } from "@tanstack/react-query";
    23→import { AnimatePresence, motion } from "framer-motion";
    24→import {
    25→	ClipboardList,
    26→	GripVertical,
    27→	Menu,
    28→	PanelLeftClose,
    29→	PanelRightClose,
    30→	Settings,
    31→	X,
    32→} from "lucide-react";
    33→import { createContext, useContext, useEffect, useState } from "react";
    34→import { toast } from "sonner";
    35→
    36→import { Button } from "@/components/ui/button";
    37→import { Card, CardContent } from "@/components/ui/card";
    38→import { Sheet, SheetContent, SheetTrigger } from "@/components/ui/sheet";
    39→import { useMediaQuery } from "@/hooks/use-media-query";
    40→import { cn } from "@/lib/utils";
    41→import { orpc } from "@/utils/orpc";
    42→import { BuilderCanvas } from "./builder-canvas";
    43→import { BuilderHeader } from "./builder-header";
    44→import { PropertiesPanel } from "./properties-panel";
    45→import { QuestionPalette } from "./question-palette";
    46→
    47→// Question type configs for drag overlay
    48→const questionTypeIcons: Record<string, React.ElementType> = {
    49→	text: ClipboardList,
    50→	textarea: ClipboardList,
    51→	multiple_choice: ClipboardList,
    52→	checkbox: ClipboardList,
    53→	dropdown: ClipboardList,
    54→	rating: ClipboardList,
    55→	nps: ClipboardList,
    56→	linear_scale: ClipboardList,
    57→	date: ClipboardList,
    58→	email: ClipboardList,
    59→	phone: ClipboardList,
    60→	file_upload: ClipboardList,
    61→};
    62→
    63→const questionTypeLabels: Record<string, string> = {
    64→	text: "Short Text",
    65→	textarea: "Long Text",
    66→	multiple_choice: "Multiple Choice",
    67→	checkbox: "Checkboxes",
    68→	dropdown: "Dropdown",
    69→	rating: "Rating",
    70→	nps: "NPS",
    71→	linear_scale: "Linear Scale",
    72→	date: "Date",
    73→	email: "Email",
    74→	phone: "Phone",
    75→	file_upload: "File Upload",
    76→};
    77→
    78→// Builder context for sharing state across components
    79→interface SurveyBuilderContextValue {
    80→	survey: Survey;
    81→	questions: Question[];
    82→	selectedQuestionId: string | null;
    83→	setSelectedQuestionId: (id: string | null) => void;
    84→	activeTab: "build" | "preview";
    85→	setActiveTab: (tab: "build" | "preview") => void;
    86→	onQuestionsChange: (questions: Question[]) => void;
    87→	paletteOpen: boolean;
    88→	setPaletteOpen: (open: boolean) => void;
    89→	propertiesOpen: boolean;
    90→	setPropertiesOpen: (open: boolean) => void;
    91→}
    92→
    93→const SurveyBuilderContext = createContext<SurveyBuilderContextValue | null>(
    94→	null,
    95→);
    96→
    97→export function useSurveyBuilder() {
    98→	const context = useContext(SurveyBuilderContext);
    99→	if (!context) {
   100→		throw new Error(
   101→			"useSurveyBuilder must be used within a SurveyBuilder component",
   102→		);
   103→	}
   104→	return context;
   105→}
   106→
   107→// Drag item types
   108→interface PaletteDragItem {
   109→	type: "palette";
   110→	questionType: Question["type"];
   111→}
   112→
   113→interface QuestionDragItem {
   114→	type: "question";
   115→	id: string;
   116→}
   117→
   118→type DragItem = PaletteDragItem | QuestionDragItem;
   119→
   120→interface SurveyBuilderProps {
   121→	survey: Survey;
   122→	questions: Question[];
   123→	className?: string;
   124→}
   125→
   126→export function SurveyBuilder({
   127→	survey,
   128→	questions: initialQuestions,
   129→	className,
   130→}: SurveyBuilderProps) {
   131→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
   132→		null,
   133→	);
   134→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
   135→	const [questions, setQuestions] = useState(initialQuestions);
   136→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   137→	const [paletteOpen, setPaletteOpen] = useState(false);
   138→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   139→
   140→	// Responsive breakpoints
   141→	const isMobile = useMediaQuery("(max-width: 639px)");
   142→	const isTablet = useMediaQuery("(min-width: 640px) and (max-width: 1023px)");
   143→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   144→
   145→	const queryClient = useQueryClient();
   146→
   147→	// Sync state when initialQuestions changes
   148→	useEffect(() => {
   149→		setQuestions(initialQuestions);
   150→	}, [initialQuestions]);
   151→
   152→	// Create question mutation (for palette drops)
   153→	const createMutation = useMutation(
   154→		orpc.question.create.mutationOptions({
   155→			onSuccess: (newQuestion) => {
   156→				setQuestions((prev) => [...prev, newQuestion]);
   157→				setSelectedQuestionId(newQuestion.id);
   158→				queryClient.invalidateQueries({ queryKey: ["question"] });
   159→				toast.success("Question added");
   160→			},
   161→			onError: (error) => {
   162→				toast.error(error.message || "Failed to create question");
   163→			},
   164→		}),
   165→	);
   166→
   167→	// Reorder mutation
   168→	const reorderMutation = useMutation(
   169→		orpc.question.reorder.mutationOptions({
   170→			onSuccess: () => {
   171→				queryClient.invalidateQueries({ queryKey: ["question"] });
   172→			},
   173→			onError: (error) => {
   174→				toast.error(error.message || "Failed to reorder questions");
   175→			},
   176→		}),
   177→	);
   178→
   179→	// DnD sensors
   180→	const sensors = useSensors(
   181→		useSensor(PointerSensor, {
   182→			activationConstraint: {
   183→				distance: 5,
   184→			},
   185→		}),
   186→		useSensor(KeyboardSensor, {
   187→			coordinateGetter: sortableKeyboardCoordinates,
   188→		}),
   189→	);
   190→
   191→	const handleDragStart = (event: DragStartEvent) => {
   192→		const { active } = event;
   193→		const data = active.data.current;
   194→
   195→		if (data?.questionType) {
   196→			// Dragging from palette
   197→			setActiveDragItem({
   198→				type: "palette",
   199→				questionType: data.questionType as Question["type"],
   200→			});
   201→		} else {
   202→			// Dragging existing question
   203→			setActiveDragItem({
   204→				type: "question",
   205→				id: active.id as string,
   206→			});
   207→		}
   208→	};
   209→
   210→	const handleDragOver = (event: DragOverEvent) => {
   211→		const { active, over } = event;
   212→
   213→		if (!over) return;
   214→
   215→		// Handle palette item over canvas (create new question)
   216→		if (
   217→			active.data.current?.questionType &&
   218→			over.id === "canvas" &&
   219→			!createMutation.isPending
   220→		) {
   221→			const questionType = active.data.current.questionType as Question["type"];
   222→			createMutation.mutate({
   223→				surveyId: survey.id,
   224→				type: questionType,
   225→				title: `New ${questionTypeLabels[questionType] || questionType}`,
   226→				order: questions.length,
   227→			});
   228→			setActiveDragItem(null);
   229→		}
   230→	};
   231→
   232→	const handleDragEnd = (event: DragEndEvent) => {
   233→		const { active, over } = event;
   234→		setActiveDragItem(null);
   235→
   236→		if (!over) return;
   237→
   238→		// Handle reordering
   239→		if (active.id !== over.id && over.id !== "canvas") {
   240→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   241→			const newIndex = questions.findIndex((q) => q.id === over.id);
   242→
   243→			if (oldIndex !== -1 && newIndex !== -1) {
   244→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   245→					(q, index) => ({
   246→						...q,
   247→						order: index,
   248→					}),
   249→				);
   250→
   251→				setQuestions(newQuestions);
   252→
   253→				reorderMutation.mutate({
   254→					questions: newQuestions.map((q) => ({
   255→						id: q.id,
   256→						order: q.order,
   257→					})),
   258→				});
   259→			}
   260→		}
   261→	};
   262→
   263→	const contextValue: SurveyBuilderContextValue = {
   264→		survey,
   265→		questions,
   266→		selectedQuestionId,
   267→		setSelectedQuestionId,
   268→		activeTab,
   269→		setActiveTab,
   270→		onQuestionsChange: setQuestions,
   271→		paletteOpen,
   272→		setPaletteOpen,
   273→		propertiesOpen,
   274→		setPropertiesOpen,
   275→	};
   276→
   277→	const safeQuestions = questions || [];
   278→
   279→	// Render drag overlay
   280→	const renderDragOverlay = () => {
   281→		if (!activeDragItem) return null;
   282→
   283→		if (activeDragItem.type === "palette") {
   284→			const Icon =
   285→				questionTypeIcons[activeDragItem.questionType] || ClipboardList;
   286→			return (
   287→				<Card className="shadow-lg">
   288→					<CardContent className="flex items-center gap-3 p-4">
   289→						<GripVertical className="h-4 w-4 text-neutral-400" />
   290→						<Icon className="h-5 w-5 text-violet-500" />
   291→						<span className="font-medium">
   292→							{questionTypeLabels[activeDragItem.questionType] ||
   293→								activeDragItem.questionType}
   294→						</span>
   295→					</CardContent>
   296→				</Card>
   297→			);
   298→		}
   299→
   300→		// Dragging existing question
   301→		const activeQuestion = safeQuestions.find(
   302→			(q) => q.id === activeDragItem.id,
   303→		);
   304→		if (activeQuestion) {
   305→			const Icon = questionTypeIcons[activeQuestion.type] || ClipboardList;
   306→			return (
   307→				<Card className="shadow-lg">
   308→					<CardContent className="flex items-center gap-3 p-4">
   309→						<GripVertical className="h-4 w-4 text-neutral-400" />
   310→						<Icon className="h-5 w-5 text-violet-500" />
   311→						<span className="font-medium">{activeQuestion.title}</span>
   312→					</CardContent>
   313→				</Card>
   314→			);
   315→		}
   316→
   317→		return null;
   318→	};
   319→
   320→	return (
   321→		<SurveyBuilderContext.Provider value={contextValue}>
   322→			<DndContext
   323→				sensors={sensors}
   324→				collisionDetection={closestCenter}
   325→				onDragStart={handleDragStart}
   326→				onDragOver={handleDragOver}
   327→				onDragEnd={handleDragEnd}
   328→			>
